-- Generated by scripts/sync-page-counters.cjs. Read-only report.
WITH pages(page, name) AS (
  VALUES
    ('exchange', '武器交換'),
    ('growth', '成長率比較'),
    ('home', 'ホーム'),
    ('inheritance', '引継ぎ仕様のまとめ'),
    ('materials', '復興素材管理'),
    ('order', '攻略順など'),
    ('other/animals', '動物入手先一覧'),
    ('other/character-weapons', 'キャラ所持武器管理'),
    ('other/characters', '個別キャラの詳細'),
    ('other/desert', '砂漠について'),
    ('other/dungeons', 'ダンジョン一覧'),
    ('other/forging', '武器錬成素材'),
    ('other', 'その他'),
    ('other/map-unlock', 'マップ開放で注意するところ'),
    ('other/scout-weapons', 'スカウト武器について'),
    ('other/verification', '検証記録'),
    ('weapons', '有用武器')
)
SELECT pages.name AS "ページ名",
       COALESCE(page_views.count, 0) AS "閲覧数",
       page_views.updated_at AS "最終更新日時（UTC）"
FROM pages
LEFT JOIN page_views ON page_views.page = pages.page
ORDER BY "閲覧数" DESC, pages.page;
